<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\ChangePasswordUsecase;

/**
 * Login step form that forces a user to change their password before completing authentication.
 *
 * This step is triggered when the authentication pipeline returns ERR_NEW_PASSWORD_REQUIRED,
 * which typically happens when an account has an expired or temporary password. The form asks
 * the user for both their current (old) password and a new one; both fields are encrypted in
 * the browser by HtmlSecurer before submission so plaintext values are never transmitted.
 *
 * On submission the ChangePasswordUsecase validates the old credential and applies the new
 * one. If the change succeeds, AuthenticateUser pre-authenticates the user and the flow
 * continues to the next step or final redirect. Failures surface a translated error message
 * and re-render the same form.
 *
 * Relationships: delegates password logic to ChangePasswordUsecase, calls AuthenticateUser
 * for post-change pre-authentication, uses HtmlSecurer for crypto/CSRF scripts, and
 * DecorateHtml for themed output.
 */
class NewPassForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
        private readonly ChangePasswordUsecase $changePassword
    ) {
    }

    /**
     * Processes the forced-password-change submission and pre-authenticates on success.
     *
     * Decrypts both the old and new password fields, delegates to ChangePasswordUsecase, and
     * calls preAuthenticate when the change is accepted. Throws LoginException with a
     * new-password-required result if the change cannot be applied.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $body = $input->body ?? [];
        $oldpass = $this->securer->decrypt($body["old_pass"]) ?? '';
        $newpass = $this->securer->decrypt($body["new_pass"]) ?? '';
        $csid = (string) ($body['csid'] ?? '');
        if ($this->changePassword->forceUpdatePassword($input->context->tenant, $input->challenges->username ?? '', $oldpass, $newpass)) {
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $input->challenges,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $input->challenges);
        }

        throw new LoginException(auth: AuthenticationResult::newPasswordRequired('unable_to_change'));
    }

    /**
     * Renders the forced-password-change form with old-password and new-password fields.
     *
     * Injects CSRF signing and in-browser field encryption scripts so that both passwords
     * are ciphered before the form is submitted. Displays any error message from the previous
     * authentication attempt.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("type_old_pass"),
            $this->securer->cypher([['from' => 'type_old_pass', 'to' => 'old_pass'],
                        ['from' => 'type_new_pass', 'to' => 'new_pass']], 'chpass'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("newpass.title");
        $errorMessage = $error?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("newpass.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("newpass.help");
        $old = $translator->get("newpass.current");
        $send = $translator->get("newpass.send");

        $backLabel = $translator->get("newpass.back-label");
        $backText = $translator->get(
            "newpass.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $backLabel . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $step = StepName::NEW_PASS->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            'New pass',
            $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    <form id="chpass" method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="new_pass" id="new_pass" value="" />
                        <input type="hidden" name="old_pass" id="old_pass" value="" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label> {$old}
                            <input type="password" id="type_old_pass" value="" />
                        </label>
                        <label>New pass
                            <input type="password" id="type_new_pass" value="" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $input->context->tenant
        ));
        return StepResult::render($response, $input->challenges);
    }
}
